    for ci in range(1,n+1):
        ar=np.argwhere(lab==ci)
        cells=[(int(y),int(x)) for y,x in ar]
        hh=max(y for y,_ in cells)-min(y for y,_ in cells)+1
        ww=max(x for _,x in cells)-min(x for _,x in cells)+1
        rset=set()
        ok=True
        for (yy,xx) in cells:
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=yy+dy,xx+dx
                    if 0<=ny<h and 0<=nx<w and A[ny][nx]==0 and (dy,dx)!=(0,0):
                        rset.add((ny,nx))
        ch={(y,x) for y,x in rset if int(B[y][x])!=0}
        bad=len(ch)>0 and any(int(B[y][x])!=colc for y,x in ch)
        # full ring zero?
        ring_all_zero=all(int(A[y][x])==0 for y,x in [(yy+dy,xx+dx) for (yy,xx) in cells for dy in(-1,0,1) for dx in(-1,0,1) if 0<=yy+dy<h and 0<=xx+dx<w and (dy,dx)!=(0,0)])
        res=(ci,(hh,ww),len(cells),sorted(rset),bad,len(ch),ring_all_zero, len(rset)==0)
        if bad: nf.append(res); print('BAD',res[:7])
        elif ring_all_zero and len(rset): fr.add(ci)
    print(p if False else 'pair','col',colc,'framed:',sorted(fr),'nframed:',len(fr),'total:',n,'bad:',len(nf))
