                    if 0<=ny<h and 0<=nx<w and int(A[ny][nx])==0:
                        rset.add((ny,nx))
        # also mark cells strictly inside bbox that are not part of any comp... no. 
        # paint ring with colc only if it is clean (no nonzero neighbor touching? )
        touch_nonzero=False
        for (yy,xx) in cells:
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=yy+dy,xx+dx
