            for r1 in range(r0,H):
                if (A[r0:r1+1,c0]!=0).any(): break
                for c1 in range(c0,W):
                    if (A[r0:r1+1,c0:c1+1]!=0).any(): break
                    # maximality: check extensions up/down/left/right
                    # up: rows above r0 over cols c0..c1 must contain nonzero
                    if r0>0 and not (A[0:r0,c0:c1+1]!=0).any(): continue  # could extend up -> not maximal
                    if c0>0 and not (A[r0:r1+1,0:c0]!=0).any(): continue  # could extend left
                    if r1<H-1 and not (A[r1+1:H,c0:c1+1]!=0).any(): continue
                    if c1<W-1 and not (A[r0:r1+1,c1+1:]!=0).any(): continue
