import numpy as np, collections, scipy.ndimage as ndi
def solve(A):
    A=np.array(A); H,W=A.shape
    cnt=collections.Counter(A[A!=0].tolist())
    inst=min(cnt,key=cnt.get)
    lab,n=ndi.label(A==0,structure=np.ones((3,3)))
    # find connected components of NONZERO cells that are NOT adjacent to grid border (via 4-conn on nonzero)
    nbz=(A!=0)
    # flood from border over nonzero
    from collections import deque
    touch=np.zeros_like(nbz,dtype=bool)
    dq=deque()
    for r in range(H):
        for c in (0,W-1):
            if nbz[r,c] and not touch[r,c]: touch[r,c]=True; dq.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if nbz[r,c] and not touch[r,c]: touch[r,c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and nbz[rr,cc] and not touch[rr,cc]:
                touch[rr,cc]=True; dq.append((rr,cc))
    # enc = nonzero not touching border; their comps via label of nbz masked by ~touch... but zeros separate them. Use label nbz then keep comps where no cell touches.
    mlab,nn=ndi.label(nbz,structure=np.ones((3,3)))
    enc=[(k,np.where(mlab==k)) for k in range(1,nn+1) if not touch[mlab==k].any()]
    out=A.copy()
    for k,(yy,xx) in enc:
        ys,xs=yy,xx
        r0,r1,c0,c1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
        for r,c in zip(ys.tolist(),xs.tolist()):
            out[r,c]=inst
    return out.tolist()
