def solve(A):
    A=np.array(A); out=A.copy()
    cnt=collections.Counter(A[A!=0].tolist())
    inst=min(cnt,key=lambda k:cnt[k])
    lab,n=ndi.label(A==0,structure=np.ones((3,3)))
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        y0,y1,x0,x1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
        if (y1-y0)<2 or (x1-x0)<2: continue
        ring={(y0,c) for c in range(x0,x1+1)}|{(y1,c) for c in range(x0,x1+1)}|{(r,x0) for r in range(y0,y1+1)}|{(r,x1) for r in range(y0,y1+1)}
        pts={(int(r),int(c)) for r,c in zip(*np.where(lab==i))}
        if len(ring-pts)>0:
            for r,c in ring:
                if out[r,c]==0: out[r,c]=inst
    return out.tolist()
